def merge_summaries(parts: list) -> str:
    """
    把多段摘要聚合成整篇摘要。
    过滤空白段；去除内容重复的段（忽略空白和标点差异）；
    用换行连接剩余段。
    """
    def is_blank(text: str) -> bool:
        """判断文本是否为空白段"""
        return text.strip() == ""

    def normalize_text(text: str) -> str:
        """去除文本中的空白和标点，用于去重键"""
        import string
        return text.translate(str.maketrans('', '', string.punctuation)).lower().strip()

    def safe_truncate(text: str, max_chars: int, ellipsis: str = '...') -> str:
        """安全截断文本"""
        if len(text) > max_chars:
            return text[:max_chars - len(ellipsis)] + ellipsis
        return text

    # 过滤空白段
    non_blank_parts = [part for part in parts if not is_blank(part.strip())]

    # 去重
    seen = set()
    unique_parts = []
    for part in non_blank_parts:
        normalized_part = normalize_text(part)
        if normalized_part not in seen:
            seen.add(normalized_part)
            unique_parts.append(part)

    # 用换行连接剩余段
    return '\n'.join(unique_parts)
